use std::env;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Default)]
struct Cli {
    name: String,
    describe: String,
    version: Option<String>,
    subcommands: Vec<Command>,
    options: Vec<OptionFlag>,
    args: Vec<Positional>,
    envs: Vec<EnvVar>,
    meta: Vec<(String, String)>,
}

#[derive(Debug, Default)]
struct Command {
    name: String,
    describe: String,
    aliases: Vec<String>,
    options: Vec<OptionFlag>,
    args: Vec<Positional>,
    envs: Vec<EnvVar>,
    command_fn: Option<String>,
}

#[derive(Debug, Default)]
struct OptionFlag {
    id: String,
    short: Option<char>,
    long: String,
    describe: String,
    is_flag: bool,
    required: bool,
    multiple: bool,
    notations: Vec<String>,
    default: Option<String>,
    choices: Option<Vec<String>>,
    choice_fn: Option<String>,
}

#[derive(Debug, Default)]
struct Positional {
    id: String,
    describe: String,
    required: bool,
    multiple: bool,
    default: Option<String>,
    choices: Option<Vec<String>>,
    choice_fn: Option<String>,
    terminated: bool, // for ~
}

#[derive(Debug, Default)]
struct EnvVar {
    name: String,
    describe: String,
    required: bool,
    default: Option<String>,
    choices: Option<Vec<String>>,
    choice_fn: Option<String>,
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && args[1].starts_with("--argc-") {
        match args[1].as_str() {
            "--argc-help" => print_help(),
            "--argc-version" => println!("argc 1.23.0"),
            "--argc-eval" => {
                if args.len() < 3 {
                    eprintln!("Usage: argc --argc-eval <FILE> <ARGS~>");
                    std::process::exit(1);
                }
                let file = &args[2];
                let cmd_args = &args[3..];
                argc_eval(file, cmd_args);
            }
            "--argc-script-path" => {
                if let Some(path) = find_argcfile() {
                    println!("{}", path.display());
                }
            }
            _ => {
                // Placeholder for other argc options
                std::process::exit(1);
            }
        }
        return;
    }

    run_command_runner(&args[1..]);
}

fn print_help() {
    println!(r#"A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval "$(argc --argc-eval "$0" "$@")"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information
"#);
}

fn find_argcfile() -> Option<PathBuf> {
    let mut curr = env::current_dir().ok()?;
    loop {
        for name in ["Argcfile.sh", "argcfile.sh", "Argcfile"] {
            let path = curr.join(name);
            if path.exists() {
                return Some(path);
            }
        }
        if !curr.pop() {
            break;
        }
    }
    None
}

fn run_command_runner(args: &[String]) {
    if let Some(argcfile) = find_argcfile() {
        let file_str = argcfile.to_str().unwrap_or("");
        // In command runner mode, it's like running argc --argc-eval Argcfile args
        // and then executing the output in bash.
        // But for simplicity, we can just execute the file with bash and pass the args.
        let mut child_args = vec![file_str.to_string()];
        child_args.extend_from_slice(args);

        let status = std::process::Command::new("bash")
            .args(&child_args)
            .status()
            .expect("failed to execute process");

        std::process::exit(status.code().unwrap_or(1));
    } else {
        eprintln!("Argcfile not found, try `argc --argc-help` for help.");
        std::process::exit(1);
    }
}

fn argc_eval(file: &str, args: &[String]) {
    let content = fs::read_to_string(file).unwrap_or_default();
    let cli = parse_script(&content);

    // TODO: Argument parsing and code generation
    println!("# Generated for {}", file);
}

fn parse_script(content: &str) -> Cli {
    let mut cli = Cli::default();
    let mut current_command: Option<Command> = None;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("# @") {
            let parts: Vec<&str> = line[3..].splitn(2, ' ').collect();
            let tag = parts[0];
            let value = if parts.len() > 1 { parts[1].trim() } else { "" };

            match tag {
                "describe" => {
                    if let Some(ref mut cmd) = current_command {
                        cmd.describe = value.to_string();
                    } else {
                        cli.describe = value.to_string();
                    }
                }
                "cmd" => {
                    if let Some(cmd) = current_command.take() {
                        cli.subcommands.push(cmd);
                    }
                    current_command = Some(Command {
                        describe: value.to_string(),
                        ..Command::default()
                    });
                }
                "alias" => {
                    if let Some(ref mut cmd) = current_command {
                        cmd.aliases.extend(value.split_whitespace().map(|s| s.to_string()));
                    }
                }
                "arg" => {
                    let arg = parse_arg(value);
                    if let Some(ref mut cmd) = current_command {
                        cmd.args.push(arg);
                    } else {
                        cli.args.push(arg);
                    }
                }
                "option" => {
                    let opt = parse_option(value, false);
                    if let Some(ref mut cmd) = current_command {
                        cmd.options.push(opt);
                    } else {
                        cli.options.push(opt);
                    }
                }
                "flag" => {
                    let opt = parse_option(value, true);
                    if let Some(ref mut cmd) = current_command {
                        cmd.options.push(opt);
                    } else {
                        cli.options.push(opt);
                    }
                }
                "env" => {
                    let env = parse_env(value);
                    if let Some(ref mut cmd) = current_command {
                        cmd.envs.push(env);
                    } else {
                        cli.envs.push(env);
                    }
                }
                "meta" => {
                    let parts: Vec<&str> = value.splitn(2, ' ').collect();
                    if parts.len() == 2 {
                        cli.meta.push((parts[0].to_string(), parts[1].to_string()));
                    } else {
                        cli.meta.push((parts[0].to_string(), String::new()));
                    }
                }
                _ => {}
            }
        } else if line.ends_with("() {") {
             if let Some(ref mut cmd) = current_command {
                 let fn_name = line[..line.len()-4].trim();
                 if cmd.name.is_empty() {
                     cmd.name = fn_name.to_string();
                 }
                 cmd.command_fn = Some(fn_name.to_string());
                 cli.subcommands.push(current_command.take().unwrap());
             }
        }
    }
    if let Some(cmd) = current_command {
        cli.subcommands.push(cmd);
    }
    cli
}

fn parse_arg(value: &str) -> Positional {
    // Simple parser for now
    let mut pos = Positional::default();
    let parts: Vec<&str> = value.splitn(2, ' ').collect();
    let mut name = parts[0];
    if parts.len() > 1 {
        pos.describe = parts[1].to_string();
    }

    if name.ends_with('!') {
        pos.required = true;
        name = &name[..name.len()-1];
    } else if name.ends_with('*') {
        pos.multiple = true;
        name = &name[..name.len()-1];
    } else if name.ends_with('+') {
        pos.required = true;
        pos.multiple = true;
        name = &name[..name.len()-1];
    } else if name.ends_with('~') {
        pos.multiple = true;
        pos.terminated = true;
        name = &name[..name.len()-1];
    }

    pos.id = name.to_string();
    pos
}

fn parse_option(value: &str, is_flag: bool) -> OptionFlag {
    let mut opt = OptionFlag { is_flag, ..OptionFlag::default() };
    // This is much more complex in reality
    opt.id = value.to_string();
    opt
}

fn parse_env(value: &str) -> EnvVar {
    EnvVar { name: value.to_string(), ..EnvVar::default() }
}
EOF
cargo build
"}

