fn parse_script(content: &str) -> Cli {
    let mut cli = Cli::default();
    let mut current_command: Option<Command> = None;

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("# @") {
            let parts: Vec<&str> = trimmed[3..].splitn(2, ' ').collect();
            let tag = parts[0];
            let value = if parts.len() > 1 { parts[1].trim() } else { "" };
            match tag {
                "describe" => {
                    if let Some(ref mut cmd) = current_command { cmd.describe = value.to_string(); }
                    else { cli.describe = value.to_string(); }
                }
                "cmd" => {
                    if let Some(cmd) = current_command.take() { cli.subcommands.push(cmd); }
                    current_command = Some(Command { describe: value.to_string(), ..Command::default() });
                }
                "alias" => {
                    if let Some(ref mut cmd) = current_command {
                        cmd.aliases.extend(value.split_whitespace().map(|s| s.to_string()));
                    }
                }
                "arg" => {
                    let arg = parse_arg(value);
                    if let Some(ref mut cmd) = current_command { cmd.args.push(arg); }
                    else { cli.args.push(arg); }
                }
                "option" | "flag" => {
                    let opt = parse_option_line(value, tag == "flag");
                    if let Some(ref mut cmd) = current_command { cmd.options.push(opt); }
                    else { cli.options.push(opt); }
                }
                _ => {}
            }
        } else if trimmed.ends_with("() {") {
             let fn_name = trimmed[..trimmed.len()-4].trim();
             if fn_name == "_argc_before" { cli.before_hook = true; }
             else if fn_name == "_argc_after" { cli.after_hook = true; }
             else if let Some(ref mut cmd) = current_command {
                 if cmd.name.is_empty() { cmd.name = fn_name.to_string(); }
                 cmd.command_fn = Some(fn_name.to_string());
                 cli.subcommands.push(current_command.take().unwrap());
             }
        }
    }
    if let Some(cmd) = current_command { cli.subcommands.push(cmd); }
    cli
}

fn parse_arg(line: &str) -> Positional {
    let mut pos = Positional::default();
    let parts: Vec<&str> = line.splitn(2, ' ').collect();
    let mut name = parts[0];
    if parts.len() > 1 { pos.describe = parts[1].to_string(); }
    if name.ends_with('!') { pos.required = true; name = &name[..name.len()-1]; }
    else if name.ends_with('*') { pos.multiple = true; name = &name[..name.len()-1]; }
    else if name.ends_with('+') { pos.required = true; pos.multiple = true; name = &name[..name.len()-1]; }
    else if name.ends_with('~') { pos.multiple = true; pos.terminated = true; name = &name[..name.len()-1]; }
    pos.id = name.to_string();
    pos
}

fn parse_option_line(line: &str, is_flag: bool) -> OptionFlag {
    let mut opt = OptionFlag { is_flag, ..OptionFlag::default() };
    let parts: Vec<&str> = line.split_whitespace().collect();
    let mut desc_start = 0;
    for (i, part) in parts.iter().enumerate() {
        if part.starts_with("--") {
            let mut name = &part[2..];
            if name.ends_with('!') { opt.required = true; name = &name[..name.len()-1]; }
            else if name.ends_with('*') { opt.multiple_occurs = true; name = &name[..name.len()-1]; }
            opt.long = Some(format!("--{}", name));
            opt.id = name.replace('-', "_");
            desc_start = i + 1;
        } else if part.starts_with('-') && part.len() == 2 {
            opt.short = Some(part.to_string());
            desc_start = i + 1;
        } else if part.starts_with('<') {
            opt.notations.push(part.to_string());
            desc_start = i + 1;
        } else { break; }
    }
    if desc_start < parts.len() { opt.describe = parts[desc_start..].join(" "); }
    opt
}

fn escape_shell(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    if s.chars().all(|c| c.is_alphanumeric() || "_-./:=".contains(c)) { return s.to_string(); }
    format!("'{}'", s.replace('\'', "'\\''"))
}

fn base64_encode(input: &[u8]) -> String {
    const CHARSET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::new();
    let mut i = 0;
    while i < input.len() {
        let b0 = input[i] as usize;
        let b1 = if i + 1 < input.len() { input[i + 1] as usize } else { 0 };
        let b2 = if i + 2 < input.len() { input[i + 2] as usize } else { 0 };
        output.push(CHARSET[b0 >> 2] as char);
        output.push(CHARSET[((b0 & 0x03) << 4) | (b1 >> 4)] as char);
        if i + 1 < input.len() { output.push(CHARSET[((b1 & 0x0F) << 2) | (b2 >> 6)] as char); } else { output.push('='); }
        if i + 2 < input.len() { output.push(CHARSET[b2 & 0x3F] as char); } else { output.push('='); }
        i += 3;
    }
    output
}
