    let mut child_args = vec![file.to_string()];
    child_args.extend_from_slice(args);
    let status = std::process::Command::new("bash")
        .args(&child_args)
        .status()
        .expect("failed to execute process");
    std::process::exit(status.code().unwrap_or(1));
